//Depth menu--------------------------------------------------------------
i = 0;
word ind\_adanc\_max = sizeof(adancimi) / sizeof(adancimi[0]) - 1;

tft.fillScreen(BLACK);
while (!digitalRead(buton\_OK)) ;
ypos = 10;
tft.setFreeFont(FSB12);
tft.drawString("Select maximum displayed depth:", xpos, ypos, GFXFF);
ypos += tft.fontHeight(GFXFF);
tft.setFreeFont(FSB9);
for (i = 0; i <= ind\_adanc\_max; i++)
{
double adancime\_temp = adancimi[i] \* rezolutie + min\_adanc;
double zecimale = adancime\_temp - floor(adancime\_temp);
String sir;
if (zecimale < (adancime\_temp / 10)) sir = String(adancime\_temp, 0) + " m";
else sir = String(adancime\_temp, 1) + " m";
char text[6];
sir.toCharArray(text, 6);
tft.drawString(text, xpos, ypos, GFXFF);
ypos += tft.fontHeight(GFXFF);
}
i = 0;
ypos = 34 + i \* tft.fontHeight(GFXFF);
tft.drawRect(90, ypos, 300, 22, RED); //Draw cursor
cont = false;
delay(1000);
do {
while (digitalRead(buton\_sus) && digitalRead(buton\_jos) && digitalRead(buton\_OK)) {
; // wait
}
delay(10);
if (!digitalRead(buton\_jos))
{
if (i < ind\_adanc\_max) {
i++;
}
else {
i = 0;
}
tft.drawRect(90, ypos, 300, 22, BLACK);
ypos = 34 + i \* tft.fontHeight(GFXFF);
tft.drawRect(90, ypos, 300, 22, RED);
delay(500);
}
else if (!digitalRead(buton\_sus))
{
if (i > 0) {
i--;
}
else {
i = ind\_adanc\_max;
}
tft.drawRect(90, ypos, 300, 22, BLACK);
ypos = 34 + i \* tft.fontHeight(GFXFF);
tft.drawRect(90, ypos, 300, 22, RED);
delay(500);
}
else if (!digitalRead(buton\_OK))
{
nr\_cel\_rez\_vert = adancimi[i];
max\_adanc = nr\_cel\_rez\_vert \* rezolutie + min\_adanc;
double pas\_adanc\_temp = (max\_adanc - min\_adanc) / 4;
i = 0;
while ((abs(pas\_adanc\_temp - pasi\_adanc[i]) > abs(pas\_adanc\_temp - pasi\_adanc[i + 1])) && ((i + 1) < (sizeof(pasi\_adanc) / sizeof(pasi\_adanc[0]) - 1)))
{
i++;
}
if (abs(pas\_adanc\_temp - pasi\_adanc[i]) > abs(pas\_adanc\_temp - pasi\_adanc[i + 1])) i++;
pas\_adanc = pasi\_adanc[i];
nr\_zecimale\_pasi\_adanc = zecimale\_pasi\_adanc[i];
cont = true;
}
} while (!cont);

